const state = { data: null, selectedDescription: null, selectedReview: null, selectedLogs: null, logsJob: null, update: null };
const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const json = (value, fallback) => { try { return typeof value === 'string' ? JSON.parse(value) : (value ?? fallback); } catch (_) { return fallback; } };
async function api(path, options={}) { const response = await fetch(path, { headers:{'Content-Type':'application/json'}, ...options }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || 'Request failed'); return payload; }
function toast(message,severity='success') { const text=String(message??''); const inferred=/error|failed|failure|unable|required|not found|missing|no generated|refused|invalid/i.test(text)?'error':/warning|available|retry|blocked|incompatible/i.test(text)?'warning':'success'; const tone=severity==='success'?inferred:severity; const el=$('#toast'); el.textContent=text; el.classList.remove('success','warning','error','show'); el.classList.add(tone==='warning'?'warning':tone==='error'?'error':'success','show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),3200); }
function statusBadge(status) { const cls = ['Completed'].includes(status)?'green':['Failed','Blocked','Duplicate'].includes(status)?'red':['Awaiting Description','Final Review'].includes(status)?'orange':['Uploading','Creating Torrent','Scanning','Generating Images'].includes(status)?'blue':''; return `<span class="badge ${cls}">${esc(status)}</span>`; }
function formatSize(bytes) { const n=Number(bytes||0); if(n<1024) return `${n} B`; if(n<1024**2) return `${(n/1024).toFixed(1)} KB`; if(n<1024**3) return `${(n/1024**2).toFixed(1)} MB`; return `${(n/1024**3).toFixed(2)} GB`; }
function render() { if(!state.data) return; renderCards(); renderJobs('#dashboard-jobs', state.data.jobs.slice(0,8)); renderJobs('#queue-list', state.data.jobs); renderTrackers(); renderSelects(); renderLogsSelect(); renderHistory(); renderSettings(); renderFolderPickers(); renderManualReleaseTracker(); renderUpdate(); renderSettingsTabs(); if(state.logsJob) renderLogsView(); }
function renderCards() { const jobs=state.data.jobs; const count=(s)=>jobs.filter(j=>j.status===s).length; const cards=[['Monitored folders',state.data.folders.length,''],['Detected jobs',count('Detected'),'orange'],['Processing',jobs.filter(j=>!['Completed','Failed','Duplicate','Awaiting Description','Final Review'].includes(j.status)).length,'blue'],['Awaiting description',count('Awaiting Description'),'orange'],['Completed',count('Completed'),'green'],['Failed / blocked',jobs.filter(j=>['Failed','Blocked','Duplicate'].includes(j.status)).length,'red']]; $('#cards').innerHTML=cards.map(c=>`<div class="card ${c[2]}"><div class="label">${c[0]}</div><div class="value">${c[1]}</div></div>`).join(''); }
function renderJobs(target, jobs) { const el=$(target); if(!jobs.length){el.innerHTML='<div class="empty">No jobs yet. Add a release folder to begin.</div>';return;} el.innerHTML=jobs.map(job=>`<div class="job-row"><div><div class="job-name">${esc(job.upload_title||job.folder_name)}</div><div class="job-meta">${statusBadge(job.status)} <span>${esc(job.stage)}</span><span>${formatSize(job.total_size)}</span><span>${Number(job.progress||0).toFixed(0)}%</span>${job.torrent_internal_name?`<span>torrent: ${esc(job.torrent_internal_name)}</span>`:''}</div>${job.error?`<div class="job-meta" style="color:var(--red)">${esc(job.error)}</div>`:''}</div><div class="job-actions">${job.status==='Awaiting Description'?`<button class="small-button good" data-open-desc="${job.id}">Build Description</button>`:''}${job.status==='Final Review'?`<button class="small-button good" data-open-review="${job.id}">Review</button>`:''}${['Failed','Duplicate','Blocked'].includes(job.status)?`<button class="small-button warn" data-retry="${job.id}">Retry</button>`:''}<button class="small-button" data-log="${job.id}">Logs</button></div></div>`).join(''); }
function renderTrackers(){ $('#tracker-status').innerHTML=state.data.trackers.map(t=>`<div class="tracker-card"><strong>${esc(t.name)}</strong><div class="job-meta">${esc(t.site_url)} <span>${t.api_key_configured?'API key configured':'API key missing'}</span></div><div class="compat ${t.bitporn_compatible?'good':'bad'}">${t.bitporn_compatible?'✓ BitPorn announce compatible':'✕ Image hosting unavailable'}<br><small>${esc(t.bitporn_validation_reason)}</small></div></div>`).join('')||'<div class="empty">No trackers configured.</div>'; }
function renderSelects(){ const descriptions=state.data.jobs.filter(j=>j.status==='Awaiting Description'||j.status==='Final Review'); const reviews=state.data.jobs.filter(j=>j.status==='Final Review'); $('#description-job').innerHTML='<option value="">Select a job</option>'+descriptions.map(j=>`<option value="${j.id}">${esc(j.upload_title||j.folder_name)} — ${esc(j.status)}</option>`).join(''); $('#review-job').innerHTML='<option value="">Select a job</option>'+reviews.map(j=>`<option value="${j.id}">${esc(j.upload_title||j.folder_name)}</option>`).join(''); if(state.selectedDescription) $('#description-job').value=state.selectedDescription; if(state.selectedReview) $('#review-job').value=state.selectedReview; }
function renderLogsSelect(){const select=$('#logs-job');if(!select)return;select.innerHTML='<option value="">Select a job</option>'+state.data.jobs.map(j=>`<option value="${j.id}">${esc(j.upload_title||j.folder_name)} — ${esc(j.status)}</option>`).join('');if(state.selectedLogs)select.value=state.selectedLogs;}
function renderLogsView(){const job=state.logsJob;if(!job)return;const logs=job.logs||[];$('#logs-summary').className='log-summary';$('#logs-summary').innerHTML=`<div class="log-summary-item"><span>Job</span><strong>${esc(job.upload_title||job.folder_name)}</strong></div><div class="log-summary-item"><span>Status</span><strong>${statusBadge(job.status)}</strong></div><div class="log-summary-item"><span>Stage</span><strong>${esc(job.stage||'')}</strong></div><div class="log-summary-item"><span>Entries</span><strong>${logs.length}</strong></div>`;$('#logs-list').innerHTML=logs.length?logs.map(log=>`<div class="log-entry"><span class="log-time">${esc(log.created_at)}</span><span class="log-level ${esc(log.level)}">${esc(log.level)}</span><span class="log-stage">${esc(log.stage||'')}</span><span class="log-message">${esc(log.message)}</span></div>`).join(''):'<div class="empty">No log entries recorded for this job.</div>';}
async function openLogs(id){state.selectedLogs=String(id);state.logsJob=await api(`/api/jobs/${id}`);show('logs');renderLogsSelect();renderLogsView();}
function renderHistory(){ renderJobs('#history-list',state.data.jobs.filter(j=>['Completed','Failed','Duplicate','Blocked'].includes(j.status))); }
function renderSettings(){ const s=state.data.settings; $('#settings-form').innerHTML=`${field('Web UI port','web_port',s.web_port,'number')}${field('Bind address','bind_address',s.bind_address)}${field('Working directory','working_directory',s.working_directory)}${field('Generated directory','generated_directory',s.generated_directory)}${field('Torrent directory','torrent_directory',s.torrent_directory)}${field('Thumb It script path','thumbit_script_path',s.thumbit_script_path)}${field('Thumb It header/logo','thumbit_header_logo',s.thumbit_header_logo)}${field('Thumb It overlay image','thumbit_overlay_image',s.thumbit_overlay_image,'text','full','Leave blank to disable the centerlongest overlay')} ${field('Thumb It command','thumbit_command',s.thumbit_command,'text','full','Use {folder}, {output}, {logo}, and {overlay} placeholders')} ${field('Thumb It centre images','thumbit_center_images',s.thumbit_center_images,'number')} ${field('Thumb It still images','thumbit_still_images',s.thumbit_still_images,'number')} ${field('Thumb It timeout','thumbit_timeout_seconds',s.thumbit_timeout_seconds,'number')} ${field('Thumb It retries','thumbit_retry_count',s.thumbit_retry_count,'number')} ${field('BitPorn image upload timeout','bitporn_upload_timeout_seconds',s.bitporn_upload_timeout_seconds,'number')} ${field('BitPorn image retries','bitporn_retry_count',s.bitporn_retry_count,'number')} ${field('BBCode image width','bbcode_image_width',s.bbcode_image_width,'number')}<label class="check full"><input type="checkbox" name="thumbit_enabled" ${s.thumbit_enabled!==false?'checked':''}> Enable Thumb It <small class="field-note">Allow automatic image generation or import of generated output.</small></label><label class="check full"><input type="checkbox" name="require_final_review" ${s.require_final_review?'checked':''}> Require final review <small class="field-note">Pause before the real tracker upload so the torrent can be inspected.</small></label><label class="check full"><input type="checkbox" name="auto_start_processing" ${s.auto_start_processing?'checked':''}> Auto-start processing <small class="field-note">Allow the background worker to process detected jobs automatically.</small></label><div class="form-actions"><button class="button primary" type="submit">Save settings</button></div>`; $('#tracker-form').innerHTML=trackerForm(state.data.trackers[0]||{}); $('#folder-form').innerHTML=`${field('Folder name','name','','text')}${field('Path','path','','text','full')}<div class="form-actions"><button class="button primary" type="submit">Add monitored folder</button></div>`; $('#folder-list').innerHTML=state.data.folders.map(f=>`<div class="job-row"><div><strong>${esc(f.name)}</strong><div class="job-meta">${esc(f.path)} · ${f.enabled?'Enabled':'Disabled'}</div></div></div>`).join('')||'<div class="empty">No folders configured.</div>'; }
function renderFolderPickers(){[['#folder-form input[name="path"]','monitor','Browse...'],['#manual-release-form input[name="source_path"]','manual','Browse...']].forEach(([selector,mode,label])=>{const input=$(selector);if(!input||input.parentElement.classList.contains('input-with-button'))return;const wrapper=document.createElement('div');wrapper.className='input-with-button';input.parentNode.insertBefore(wrapper,input);wrapper.appendChild(input);const button=document.createElement('button');button.type='button';button.className='small-button';button.dataset.browseFolder=mode;button.textContent=label;wrapper.appendChild(button);});}
function renderManualReleaseTracker(){ const select=$('#manual-release-tracker'); if(!select) return; select.innerHTML=state.data.trackers.map(t=>`<option value="${t.id}">${esc(t.name)}${t.bitporn_compatible?'':' — incompatible'}</option>`).join(''); }
function renderUpdate(){ const s=state.data.settings; if(!document.querySelector('[name="github_version_url"]')){ const anchor=document.querySelector('#settings-form .form-actions'); if(anchor){ anchor.insertAdjacentHTML('beforebegin',`${field('GitHub version.txt URL','github_version_url',s.github_version_url||'','text','full','Example: https://raw.githubusercontent.com/OWNER/REPO/main/version.txt')}${field('Update check timeout','update_check_timeout_seconds',s.update_check_timeout_seconds||10,'number')}<label class="check full"><input type="checkbox" name="update_check_enabled" ${s.update_check_enabled!==false?'checked':''}> Enable GitHub update checks <small class="field-note">Allow the Settings button to compare the installed version with GitHub.</small></label>`); } } const u=state.update; const local=esc(state.data.app_version||'0.1.0'); if(!u){ $('#update-card').innerHTML=`<div class="update-line"><div><strong>Application updates</strong><div class="job-meta">Installed version: ${local}</div></div><button class="small-button" id="check-updates">Check for updates</button></div>`; return; } const cls=u.status==='Update available'?'warn':u.status==='Error'?'error':u.status==='Up to date'?'good':''; $('#update-card').innerHTML=`<div class="update-line"><div><strong>Application updates</strong><div class="job-meta">Installed: ${esc(u.local_version||local)} · GitHub: ${esc(u.remote_version||'not available')}</div><div class="compat ${cls==='good'?'good':cls==='error'?'bad':''}">${esc(u.status)}</div>${u.error?`<div class="job-meta" style="color:var(--red)">${esc(u.error)}</div>`:''}</div><button class="small-button" id="check-updates">Check again</button></div>`; }
const SETTING_NOTES={application_name:'Name shown in the browser title and application interface.',web_port:'Local TCP port used by the web interface.',bind_address:'Network interface to listen on; keep 127.0.0.1 for local-only access.',working_directory:'Temporary working files used while jobs are processed.',generated_directory:'Separate location for generated assets; original media is not modified.',torrent_directory:'Where newly created .torrent files are stored.',thumbit_script_path:'Path to the copied Pumpkin\'s Thumb It application.',thumbit_header_logo:'Header/logo image used by Pumpkin\'s Thumb It output.',thumbit_overlay_image:'Image stamped onto centerlongest output; leave blank to disable it.',thumbit_command:'Optional headless command used to run Thumb It automatically.',thumbit_center_images:'Number of centre screenshot sheets to generate.',thumbit_still_images:'Number of additional still images to prepare.',thumbit_timeout_seconds:'Maximum time allowed for a Thumb It run.',thumbit_retry_count:'Number of times a failed Thumb It run may be retried.',bitporn_upload_timeout_seconds:'Maximum time allowed for the BitPorn upload request.',bitporn_retry_count:'Number of retries for failed BitPorn image/upload operations.',bbcode_image_width:'Width used by generated image BBCode.',github_version_url:'Raw GitHub URL containing the latest version number.',update_check_timeout_seconds:'Maximum time allowed for the GitHub version check.',name:'Friendly name for this monitored folder.',path:'Folder whose child release folders should become jobs.',site_url:'Public tracker website address.',api_url:'Tracker API base address.',upload_endpoint:'Exact HTTPS API endpoint used for torrent uploads.',announce_url:'Private tracker announce identity embedded in created torrents.',api_key:'Tracker API token; it is stored masked and never returned to the browser.',default_category:'Default tracker category ID.',default_type:'Default tracker type ID.',default_resolution:'Default tracker resolution ID.',category_map_json:'JSON label-to-ID map used to populate the Build Description category dropdown.',type_map_json:'JSON label-to-ID map used to populate the Build Description type dropdown.',resolution_map_json:'JSON label-to-ID map used to populate the Build Description resolution dropdown.'};
function field(label,name,value='',type='text',extra='',hint=''){const note=hint||SETTING_NOTES[name]||'';return `<div class="field ${extra}"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}">${note?`<small class="field-note">${note}</small>`:''}</div>`;}
function jsonField(label,name,value='',hint=''){return `<div class="field full"><label>${label}</label><textarea name="${name}">${esc(value||'{}')}</textarea><small class="field-note">${hint}</small></div>`;}
function jsonObject(value){try{const parsed=typeof value==='string'?JSON.parse(value||'{}'):(value||{});return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{};}catch(_){return {};}}
function mappingOptions(raw,selected){const entries=Object.entries(jsonObject(raw)).map(([label,id])=>({label:String(label),value:String(id)}));const selectedValue=String(selected||'');const options=entries.map(item=>`<option value="${esc(item.value)}" ${item.value===selectedValue?'selected':''}>${esc(item.label)} (${esc(item.value)})</option>`);if(selectedValue&&!entries.some(item=>item.value===selectedValue))options.unshift(`<option value="${esc(selectedValue)}" selected>ID ${esc(selectedValue)}</option>`);return `<option value="">Select...</option>${options.join('')}`;}
function trackerForm(t){return `${field('Tracker name','name',t.name||'BitPorn')}${field('Site URL','site_url',t.site_url||'https://bitporn.eu')}${field('API URL','api_url',t.api_url||'https://bitporn.eu/api')}${field('Upload endpoint','upload_endpoint',t.upload_endpoint||'https://bitporn.eu/api/torrents/upload','text','full')}${field('Announce URL','announce_url',t.announce_url||'https://bitporn.eu/announce','text','full')} ${field('API key / token','api_key','','password','',t.api_key_configured?'Leave blank to keep current secret':'Required for live upload')}${field('Default category ID','default_category',t.default_category||'')}${field('Default type ID','default_type',t.default_type||'')}${field('Default resolution ID','default_resolution',t.default_resolution||'')}${jsonField('Category mappings','category_map_json',t.category_map_json,'JSON label-to-ID map, for example {"JAV":12,"Movies":13}.')}${jsonField('Type mappings','type_map_json',t.type_map_json,'JSON label-to-ID map used by the Build Description type dropdown.')}${jsonField('Resolution mappings','resolution_map_json',t.resolution_map_json,'JSON label-to-ID map used by the Build Description resolution dropdown.')}<div class="form-actions"><button class="button primary" type="submit">Save tracker</button></div>`;}
async function load(){ state.data=await api('/api/state'); state.update=state.data.update||null; if(!document.querySelector('[data-browse-folder][disabled]'))render(); }
function show(view){const titles={dashboard:'Dashboard',queue:'Queue',description:'Build Description',review:'Final Review',history:'History',logs:'Logs','bbcode-lab':'BBCode Lab',settings:'Settings'};const subtitles={dashboard:'Prepare, check and send releases without losing sight of what the worker is doing.',queue:'See every detected release and where it currently sits in the processing pipeline.',description:'Finish metadata, BBCode and upload options before moving a release to final review.',review:'Check the finished torrent package before it is submitted to the tracker.',history:'Look back through completed, failed, blocked and duplicate release jobs.',logs:'Inspect job diagnostics and processing stages when you need to trace a problem.', 'bbcode-lab':'Test Unit3D-compatible descriptions in a blank BBCode workspace.',settings:'Manage local processing, tracker details, monitored folders and update preferences.'};document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===view));document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const title=titles[view]||'Dashboard';$('#page-title').textContent=title;const subtitle=document.querySelector('.page-subtitle');if(subtitle)subtitle.textContent=subtitles[view]||subtitles.dashboard;document.title=`${title} · Pumpkin Forge`; }
async function openDescription(id){ state.selectedDescription=String(id); show('description'); $('#description-job').value=id; const job=await api(`/api/jobs/${id}`); const tags=json(job.tags_json,[]); const images=job.images||[]; const defaultDescription=job.description||`[size=20][b]${job.upload_title||job.torrent_internal_name}[/b][/size]\n\n[center][upimg0][/center]\n\n[b]MediaInfo[/b]\n${job.media_json?JSON.stringify(json(job.media_json,{}),null,2):''}`; $('#description-editor').innerHTML=`<div class="editor"><div><div class="form-grid"><div class="field"><label>Upload display name</label><input id="d-title" value="${esc(job.upload_title||job.torrent_internal_name)}"></div><div class="field"><label>Category ID</label><input id="d-category" value="${esc(job.category)}"></div><div class="field"><label>Type ID</label><input id="d-type" value="${esc(job.type)}"></div><div class="field"><label>Resolution ID</label><input id="d-resolution" value="${esc(job.resolution)}"></div><div class="field full"><label>Tags (comma separated)</label><input id="d-tags" value="${esc(tags.join(', '))}"></div><div class="field full"><label>BBCode description</label><textarea id="d-description">${esc(defaultDescription)}</textarea></div><label class="check"><input type="checkbox" id="d-anonymous" ${job.anonymous?'checked':''}> Anonymous upload</label><label class="check"><input type="checkbox" id="d-moderation" ${job.moderation_queue?'checked':''}> Moderation queue</label><label class="check"><input type="checkbox" id="d-personal" ${job.personal_release?'checked':''}> Personal release</label><label class="check"><input type="checkbox" id="d-internal" ${job.internal?'checked':''}> Internal release</label></div><div class="asset-grid">${images.map((img,i)=>`<button type="button" class="asset" data-insert="[upimg${i}]">Insert ${esc(img.image_type)}: ${esc(img.file_name)}</button>`).join('')}</div><div style="margin-top:14px;display:flex;justify-content:flex-end"><button class="button primary" id="save-description">Save draft and continue to review</button></div></div><div><p class="eyebrow">Preview</p><div class="preview" id="description-preview"></div><p class="eyebrow" style="margin-top:18px">Torrent</p><div class="review-item"><span>Internal name</span><strong>${esc(job.torrent_internal_name)}</strong><span style="margin-top:10px">Info hash</span><strong>${esc(job.info_hash)}</strong><span style="margin-top:10px">Torrent file</span><strong>${esc(job.torrent_path)}</strong><span style="margin-top:10px">File set</span><strong>${job.files.length} file(s) · ${formatSize(job.total_size)}</strong></div><p class="eyebrow" style="margin-top:18px">Prepared images</p><div class="asset-grid">${images.map((img,i)=>`<div class="asset">${esc(img.file_name)}<br><span>${esc(img.status)}</span></div>`).join('')}</div></div></div>`; const updatePreview=()=>$('#description-preview').textContent=$('#d-description').value; $('#d-description').addEventListener('input',updatePreview); updatePreview(); document.querySelectorAll('[data-insert]').forEach(btn=>btn.addEventListener('click',()=>{const area=$('#d-description'); area.value += `\n${btn.dataset.insert}\n`; updatePreview();})); $('#save-description').onclick=async()=>{try{await api(`/api/jobs/${id}/description`,{method:'POST',body:JSON.stringify({upload_title:$('#d-title').value,category:$('#d-category').value,type:$('#d-type').value,resolution:$('#d-resolution').value,tags:$('#d-tags').value,description:$('#d-description').value,anonymous:$('#d-anonymous').checked,moderation_queue:$('#d-moderation').checked,personal_release:$('#d-personal').checked,internal:$('#d-internal').checked})});toast('Description saved; job moved to Final Review');await load();openReview(id);}catch(e){toast(e.message)}}; }
async function openReview(id){ state.selectedReview=String(id); show('review'); $('#review-job').value=id; const job=await api(`/api/jobs/${id}`); const logs=(job.logs||[]).map(l=>`${l.created_at} ${l.level.toUpperCase()} ${l.message}`).join('\n'); $('#review-content').innerHTML=`<div class="review-list"><div class="review-item"><span>Upload title</span><strong>${esc(job.upload_title)}</strong></div><div class="review-item"><span>Status</span><strong>${statusBadge(job.status)}</strong></div><div class="review-item"><span>Torrent internal name</span><strong>${esc(job.torrent_internal_name)}</strong></div><div class="review-item"><span>Info hash</span><strong>${esc(job.info_hash)}</strong></div><div class="review-item"><span>Torrent file</span><strong>${esc(job.torrent_path)}</strong></div><div class="review-item"><span>Tracker</span><strong>${esc((state.data.trackers.find(t=>t.id===job.tracker_id)||{}).name||'Unknown')}</strong></div><div class="review-item"><span>Flags</span><strong>Anonymous: ${job.anonymous?'Yes':'No'} · Moderation: ${job.moderation_queue?'Yes':'No'} · Personal: ${job.personal_release?'Yes':'No'} · Internal: ${job.internal?'Yes':'No'}</strong></div></div><p class="eyebrow">Torrent contents</p><div class="asset-grid">${(job.files||[]).map(file=>`<div class="asset">${esc(file.relative_path)} · ${formatSize(file.size)}</div>`).join('')}</div><p class="eyebrow" style="margin-top:18px">Description</p><div class="preview" style="min-height:180px">${esc(job.description)}</div><p class="eyebrow" style="margin-top:18px">Prepared images</p><div class="asset-grid">${(job.images||[]).map(img=>`<div class="asset">${esc(img.image_type)} · ${esc(img.file_name)} · ${esc(img.status)}</div>`).join('')}</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px"><button class="button ghost" data-open-desc="${id}">Edit description</button><button class="button primary" id="approve-upload">Approve and upload</button></div><p class="eyebrow" style="margin-top:22px">Logs</p><div class="log-box">${esc(logs)}</div>`; const tracker=state.data.trackers.find(t=>Number(t.id)===Number(job.tracker_id)); const trackerName=tracker?.name||'selected tracker'; $('#approve-upload').onclick=async()=>{if(!confirm(`Approve and submit this torrent to ${trackerName}?`))return;try{await api(`/api/jobs/${id}/approve`,{method:'POST',body:'{}'});toast('Upload started');await load();openReview(id);}catch(e){toast(e.message)}}; document.querySelector('[data-open-desc]')?.addEventListener('click',()=>openDescription(id)); }
document.addEventListener('click',async(e)=>{const nav=e.target.closest('[data-view]');if(nav)show(nav.dataset.view);const link=e.target.closest('[data-view-link]');if(link)show(link.dataset.viewLink);const desc=e.target.closest('[data-open-desc]');if(desc)openDescription(desc.dataset.openDesc);const rev=e.target.closest('[data-open-review]');if(rev)openReview(rev.dataset.openReview);const retry=e.target.closest('[data-retry]');if(retry){try{await api(`/api/jobs/${retry.dataset.retry}/retry`,{method:'POST',body:'{}'});toast('Job queued for retry');await load()}catch(err){toast(err.message)}}const logs=e.target.closest('[data-log]');if(logs)openLogs(logs.dataset.log).catch(err=>toast(err.message));});
document.addEventListener('click',async(e)=>{if(e.target.closest('#check-updates')){try{const result=await api('/api/update-check',{method:'POST',body:'{}'});state.update=result.update;renderUpdate();toast(result.update.status)}catch(err){toast(err.message)}}});
$('#refresh').onclick=load; $('#description-job').onchange=(e)=>e.target.value&&openDescription(e.target.value); $('#review-job').onchange=(e)=>e.target.value&&openReview(e.target.value); $('#logs-job').onchange=(e)=>e.target.value&&openLogs(e.target.value).catch(err=>toast(err.message));
document.addEventListener('submit',async(e)=>{e.preventDefault();e.stopPropagation();const form=e.target;const data=Object.fromEntries(new FormData(form).entries());const view=document.querySelector('.view.active')?.id;const scrollY=window.scrollY;if(form.id==='settings-form'){for(const key of ['thumbit_enabled','require_final_review','auto_start_processing','update_check_enabled'])data[key]=Boolean(form.elements[key]?.checked);for(const key of ['web_port','thumbit_center_images','thumbit_still_images','thumbit_timeout_seconds','thumbit_retry_count','bitporn_upload_timeout_seconds','bitporn_retry_count','bbcode_image_width','update_check_timeout_seconds'])if(key in data)data[key]=Number(data[key]);try{await api('/api/settings',{method:'POST',body:JSON.stringify(data)});toast('Settings saved');await load();show(view||'settings');requestAnimationFrame(()=>window.scrollTo(0,scrollY));}catch(err){toast(err.message)}}if(form.id==='tracker-form'){try{await api('/api/trackers',{method:'POST',body:JSON.stringify(data)});toast('Tracker saved');await load();show(view||'settings');requestAnimationFrame(()=>window.scrollTo(0,scrollY));}catch(err){toast(err.message)}}if(form.id==='folder-form'){try{await api('/api/folders',{method:'POST',body:JSON.stringify({name:data.name,path:data.path,enabled:1,include_subfolders:0,scan_interval_seconds:20,minimum_folder_age_seconds:60,stability_interval_seconds:10,stable_checks:2,default_tracker_id:state.data.trackers[0]?.id||null,ignore_patterns_json:'[]',include_patterns_json:'[]'})});toast('Folder monitoring added');await load();show(view||'settings');requestAnimationFrame(()=>window.scrollTo(0,scrollY));}catch(err){toast(err.message)}}if(form.id==='manual-release-form'){try{await api('/api/jobs',{method:'POST',body:JSON.stringify({source_path:data.source_path,tracker_id:Number(data.tracker_id)})});toast('Local release added to the persistent queue');form.reset();await load();show('queue')}catch(err){toast(err.message)}}});
document.addEventListener('click',async(e)=>{const browse=e.target.closest('[data-browse-folder]');if(!browse)return;const input=browse.closest('.field')?.querySelector('input');if(!input)return;const mode=browse.dataset.browseFolder;const originalLabel=browse.textContent;browse.disabled=true;browse.textContent='Opening...';try{const result=await api('/api/browse-folder',{method:'POST',body:JSON.stringify({initial_path:input.value})});if(result.path){const currentInput=mode==='monitor'?$('#folder-form input[name="path"]'):$('#manual-release-form input[name="source_path"]');(currentInput||input).value=result.path;if(mode==='monitor'){const nameInput=$('#folder-form input[name="name"]');if(nameInput&&!nameInput.value.trim())nameInput.value=result.path.split(/[\\/]+/).filter(Boolean).pop()||'';}}}catch(err){toast(err.message)}finally{browse.disabled=false;browse.textContent=originalLabel;}});
