function groupSettingsFields(){const form=$('#settings-form');if(!form||form.querySelector('.settings-bubble'))return;const groups=[['Application','Basic application identity, network access, and storage locations.',['application_name','web_port','bind_address','working_directory','generated_directory','torrent_directory']],['Thumbnail generation','Controls for the bundled Pumpkin\'s Thumb It image generator.',['thumbit_enabled','thumbit_script_path','thumbit_header_logo','thumbit_logo_url','thumbit_overlay_image','thumbit_command','thumbit_center_images','thumbit_still_images','thumbit_timeout_seconds','thumbit_retry_count']],['Upload and workflow','Controls for image uploads and the review workflow.',['bitporn_upload_timeout_seconds','bitporn_retry_count','bbcode_image_width','require_final_review','auto_start_processing']],['Application updates','Optional GitHub version checking for this app.',['github_version_url','update_check_timeout_seconds','update_check_enabled']]];const elements={};form.querySelectorAll(':scope > [name], :scope > .field, :scope > .check').forEach(el=>{const input=el.matches('[name]')?el:el.querySelector('[name]');if(input)elements[input.name]=el;});const actions=form.querySelector(':scope > .form-actions');groups.forEach(([title,description,names])=>{const bubble=document.createElement('section');bubble.className='settings-bubble';bubble.innerHTML=`<div class="settings-bubble-head"><p class="eyebrow">Settings group</p><h3>${title}</h3><p>${description}</p></div>`;let moved=0;names.forEach(name=>{if(elements[name]){bubble.appendChild(elements[name]);moved++;}});if(moved)form.insertBefore(bubble,actions||null);});if(actions)form.appendChild(actions);}
const originalRenderUpdate=renderUpdate;
renderUpdate=()=>{originalRenderUpdate();groupSettingsFields();};
const originalOpenDescription=openDescription;
openDescription=async function(id){await originalOpenDescription(id);const job=await api(`/api/jobs/${id}`);const tracker=state.data.trackers.find(t=>Number(t.id)===Number(job.tracker_id))||{};const fields=[['d-category','Category',tracker.category_map_json,job.category||tracker.default_category||'','Choose the tracker category for this upload.'],['d-type','Type',tracker.type_map_json,job.type||tracker.default_type||'','Choose the tracker type for this upload.'],['d-resolution','Resolution',tracker.resolution_map_json,job.resolution||tracker.default_resolution||'','Choose the tracker resolution for this upload.']];fields.forEach(([id,label,mapping,selected,note])=>{const input=$(`#${id}`);if(!input)return;const wrapper=input.parentElement;wrapper.querySelector('label').textContent=label;const select=document.createElement('select');select.id=id;select.innerHTML=mappingOptions(mapping,selected);input.replaceWith(select);const help=document.createElement('small');help.className='field-note';help.textContent=note;wrapper.appendChild(help);});};
function renderBbcode(value,jobId,images=[]){let html=esc(value||'');const imageAt=(index)=>{const image=images[index];if(!image)return `<span class="bbcode-missing">[upimg${index}]</span>`;const fileName=cleanFilenameDisplay(image.file_name||'Prepared image');return `<figure class="bbcode-image"><img src="/api/jobs/${Number(jobId)}/image/${Number(image.id)}" alt="${esc(fileName)}" title="Click to enlarge"><figcaption>${esc(fileName)} · click image to enlarge</figcaption></figure>`;};html=html.replace(/\[upimg(\d*)\]/gi,(_,index)=>imageAt(index===''?0:Number(index)));html=html.replace(/\[b\]([\s\S]*?)\[\/b\]/gi,'<strong>$1</strong>').replace(/\[i\]([\s\S]*?)\[\/i\]/gi,'<em>$1</em>').replace(/\[u\]([\s\S]*?)\[\/u\]/gi,'<u>$1</u>').replace(/\[size=(\d{1,3})\]([\s\S]*?)\[\/size\]/gi,(_,size,body)=>`<span style="font-size:${Math.min(72,Math.max(8,Number(size)))}px">${body}</span>`).replace(/\[center\]([\s\S]*?)\[\/center\]/gi,'<div class="bbcode-center">$1</div>').replace(/\[quote\]([\s\S]*?)\[\/quote\]/gi,'<blockquote>$1</blockquote>').replace(/\[url=(https?:\/\/[^\]\s]+)\]([\s\S]*?)\[\/url\]/gi,'<a href="$1" target="_blank" rel="noreferrer">$2</a>').replace(/\[br\]/gi,'<br>');return html.replace(/\r?\n/g,'<br>');}
const originalRenderSelectsWithDescriptionCards=renderSelects;
renderSelects=()=>{originalRenderSelectsWithDescriptionCards();const select=$('#description-job');if(!select)return;select.style.display='none';const anchor=$('#description-editor');if(!anchor)return;let wrap=$('#description-job-cards');if(!wrap){wrap=document.createElement('div');wrap.id='description-job-cards';wrap.className='description-job-cards';wrap.innerHTML='<p class="eyebrow">Jobs awaiting description</p><div class="job-list" id="description-job-list"></div>';anchor.parentNode.insertBefore(wrap,anchor);}renderJobs('#description-job-list',state.data.jobs.filter(job=>job.status==='Awaiting Description'||job.status==='Final Review'));};
const originalOpenDescriptionForLivePreview=openDescription;
openDescription=async function(id){await originalOpenDescriptionForLivePreview(id);const area=$('#d-description');const preview=$('#description-preview');if(!area||!preview)return;const editor=document.querySelector('.editor');if(editor){editor.classList.add('description-two-pane');editor.children[0]?.classList.add('description-bbcode-editor-pane');editor.children[1]?.classList.add('description-bbcode-preview-pane');}const job=await api(`/api/jobs/${id}`);const typeNote=$('#d-type')?.parentElement.querySelector('.field-note');if(typeNote)typeNote.textContent='Tracker classification used to categorize and filter this upload.';const descriptionLabel=area.parentElement.querySelector('label');if(descriptionLabel&&!descriptionLabel.querySelector('#description-design')){descriptionLabel.className='label-with-control';descriptionLabel.innerHTML='<span>BBCode description — edit here</span><select id="description-design" disabled title="Premade designs are coming soon"><option>Coming Soon...</option></select>';}const openImage=(src,alt)=>{let modal=$('#bbcode-image-modal');if(!modal){modal=document.createElement('div');modal.id='bbcode-image-modal';modal.className='bbcode-image-modal';modal.innerHTML='<div class="bbcode-image-modal-card"><button type="button" class="small-button bbcode-image-modal-close">Close</button><img><p></p></div>';document.body.appendChild(modal);modal.addEventListener('click',event=>{if(event.target===modal||event.target.closest('.bbcode-image-modal-close'))modal.classList.remove('show');});}modal.querySelector('img').src=src;modal.querySelector('img').alt=alt||'Expanded preview';modal.querySelector('p').textContent=alt||'';modal.classList.add('show');};const updatePreview=()=>{preview.classList.add('bbcode-rendered');preview.innerHTML=renderBbcode(area.value,id,job.images||[]);preview.querySelectorAll('.bbcode-image img').forEach(image=>image.addEventListener('click',()=>openImage(image.src,image.alt)));};area.addEventListener('input',updatePreview);updatePreview();};
const originalOpenDescriptionForThumbRegeneration=openDescription;
openDescription=async function(id){await originalOpenDescriptionForThumbRegeneration(id);const preview=$('#description-preview');if(!preview)return;const heading=preview.previousElementSibling;if(!heading||heading.querySelector('#regenerate-thumbnails'))return;heading.className='eyebrow preview-heading';heading.innerHTML='<span><strong>LIVE WEBSITE VIEW — BBCode</strong><small>This is the rendered appearance visitors will see on the tracker</small></span><button type="button" class="small-button" id="regenerate-thumbnails">Regenerate thumbnails</button>';const button=$('#regenerate-thumbnails');button.onclick=async()=>{button.disabled=true;button.textContent='Regenerating...';try{await api(`/api/jobs/${id}/regenerate-thumbnails`,{method:'POST',body:'{}'});toast('Thumbnail regeneration started');for(let attempt=0;attempt<90;attempt++){await new Promise(resolve=>setTimeout(resolve,2000));const latest=await api(`/api/jobs/${id}`);if(latest.status==='Awaiting Description'){toast('Thumbnail regeneration completed');await openDescription(id);return;}if(['Failed','Blocked'].includes(latest.status)){toast(latest.error||'Thumbnail regeneration failed','error');await openDescription(id);return;}}toast('Thumbnail regeneration is still running; refresh the page to check it.','warning');}catch(err){toast(err.message);button.disabled=false;button.textContent='Regenerate thumbnails';}};};
function jobProgressHtml(job){const raw=Number(job.progress);const progress=Number.isFinite(raw)?Math.max(0,Math.min(100,raw)):0;const status=String(job.status||'');const explanations={'Detected':'Queued and waiting to start','Waiting For Files':'Waiting for the release files to finish copying','Scanning':'Scanning the release media','Generating Images':'Creating preview images with Thumb It','Creating Torrent':'Building the private torrent','Validating Tracker':'Checking the tracker settings','Uploading Images':'Preparing images for upload','Awaiting Description':'Waiting for you to build the upload description','Final Review':'Waiting for your final review before upload','Uploading':'Submitting the torrent to the tracker','Completed':'Upload completed successfully','Failed':'Processing stopped because of an error','Duplicate':'Skipped because a duplicate was found','Blocked':'Waiting for an issue to be resolved'};const explanation=job.error&&status==='Failed'?`Processing stopped: ${job.error}`:(explanations[status]||job.stage||status||'Queued');const tone=status==='Completed'?'complete':['Failed','Blocked','Duplicate'].includes(status)?'error':['Awaiting Description','Final Review','Waiting For Files'].includes(status)?'waiting':'active';return `<div class="job-progress"><div class="job-progress-head"><span>What\'s happening: ${esc(explanation)}</span><strong>${progress.toFixed(0)}% complete</strong></div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.toFixed(0)}" aria-label="${esc(explanation)}"><div class="progress-fill ${tone}" style="width:${progress}%"></div></div></div>`;}
const originalRenderJobsWithProgress=renderJobs;
renderJobs=(target,jobs)=>{originalRenderJobsWithProgress(target,jobs);const container=$(target);if(!container)return;container.querySelectorAll('.job-row').forEach((row,index)=>{const job=jobs[index];if(!job)return;[...row.querySelectorAll('.job-meta span')].find(node=>/^\d+(?:\.\d+)?%$/.test(node.textContent.trim()))?.remove();row.firstElementChild?.insertAdjacentHTML('beforeend',jobProgressHtml(job));});};
const originalRenderJobsWithoutStaleErrors=renderJobs;
renderJobs=(target,jobs)=>{originalRenderJobsWithoutStaleErrors(target,jobs);const container=$(target);if(!container)return;container.querySelectorAll('.job-row').forEach((row,index)=>{if(['Failed','Blocked','Duplicate'].includes(jobs[index]?.status))return;row.querySelectorAll('.job-meta').forEach(meta=>{if((meta.getAttribute('style')||'').includes('--red'))meta.remove();});});};
function renderMonitorStatus(){const cards=$('#cards');if(!cards)return;let el=$('#monitor-status');if(!el){el=document.createElement('div');el.id='monitor-status';el.className='monitor-status';cards.insertAdjacentElement('afterend',el);}const status=state.data.monitor_status||{};if(!status.active||!Number(status.remaining)){el.hidden=true;el.innerHTML='';return;}el.hidden=false;el.innerHTML=`<strong>Processing files without folders: ${Number(status.remaining)} of ${Number(status.total)||Number(status.remaining)} remaining</strong><span>Organizing one release at a time to reduce drive activity.</span>`;}
const originalRenderCardsWithMonitorStatus=renderCards;
renderCards=()=>{originalRenderCardsWithMonitorStatus();renderMonitorStatus();};
load().catch(e=>toast(e.message)); setInterval(()=>{if(document.visibilityState==='visible')load().catch(()=>{})},5000);

const originalRenderSettingsWithMetadata=renderSettings;
renderSettings=()=>{originalRenderSettingsWithMetadata();const form=$('#settings-form');const anchor=form?.querySelector('.form-actions');if(!form||!anchor||form.querySelector('[name="theporndb_api_url"]'))return;const s=state.data.settings||{};anchor.insertAdjacentHTML('beforebegin',`<div class="field full"><label>Metadata matching</label><small class="field-note">Use configured provider APIs to suggest titles, studios, dates, performers, tags, and JAV codes before description editing.</small></div>${field('Metadata search results','metadata_search_results',s.metadata_search_results||5,'number')}${field('Minimum match confidence','metadata_min_confidence',s.metadata_min_confidence||55,'number','', 'Only matches at or above this score are considered confident.')}${field('Provider timeout','metadata_timeout_seconds',s.metadata_timeout_seconds||15,'number')}${field('ThePornDB API URL','theporndb_api_url',s.theporndb_api_url||'','text','full','ThePornDB REST API base URL.')}${field('ThePornDB API token','theporndb_api_token','','password','full',s.theporndb_api_token_configured?'Leave blank to keep the saved token.':'Add a token to enable ThePornDB searches.')}${field('StashDB GraphQL URL','stashdb_api_url',s.stashdb_api_url||'','text','full','Stash-Box GraphQL endpoint for scene matching.')}${field('StashDB API token','stashdb_api_token','','password','full',s.stashdb_api_token_configured?'Leave blank to keep the saved token.':'Add a token to enable StashDB searches.')}${field('javinfo API URL','javinfo_api_url',s.javinfo_api_url||'','text','full','javinfo API endpoint for JAV and studio lookups.')}${field('javinfo API token','javinfo_api_token','','password','full',s.javinfo_api_token_configured?'Leave blank to keep the saved token.':'Add a token to enable javinfo searches.') }<label class="check full"><input type="checkbox" name="metadata_auto_identify" ${s.metadata_auto_identify!==false?'checked':''}> Identify metadata automatically <small class="field-note">Run one provider search after the local media scan; provider errors do not stop the job.</small></label><label class="check full"><input type="checkbox" name="metadata_theporndb_enabled" ${s.metadata_theporndb_enabled!==false?'checked':''}> Enable ThePornDB <small class="field-note">General adult scene, studio, performer, and JAV metadata when the API token is configured.</small></label><label class="check full"><input type="checkbox" name="metadata_stashdb_enabled" ${s.metadata_stashdb_enabled!==false?'checked':''}> Enable StashDB <small class="field-note">Scene matching through the configured Stash-Box GraphQL endpoint.</small></label><label class="check full"><input type="checkbox" name="metadata_javinfo_enabled" ${s.metadata_javinfo_enabled!==false?'checked':''}> Enable javinfo <small class="field-note">JAV title, code, studio, and release lookups.</small></label>`);};
const originalRenderUpdateWithMetadata=renderUpdate;
renderUpdate=()=>{originalRenderUpdateWithMetadata();const form=$('#settings-form');if(!form||form.querySelector('#metadata-settings-bubble'))return;const names=['metadata_search_results','metadata_min_confidence','metadata_timeout_seconds','theporndb_api_url','theporndb_api_token','stashdb_api_url','stashdb_api_token','javinfo_api_url','javinfo_api_token','metadata_auto_identify','metadata_theporndb_enabled','metadata_stashdb_enabled','metadata_javinfo_enabled'];const bubble=document.createElement('section');bubble.id='metadata-settings-bubble';bubble.className='settings-bubble';bubble.innerHTML='<div class="settings-bubble-head"><p class="eyebrow">Settings group</p><h3>Metadata providers</h3><p>Optional provider searches suggest release metadata for manual confirmation. Tokens stay on this machine and are never sent to the browser.</p></div>';const actions=form.querySelector('.form-actions');let moved=0;names.forEach(name=>{const input=form.querySelector(`[name="${name}"]`);const item=input?.closest('.field,.check');if(item&&item.parentElement===form){bubble.appendChild(item);moved++;}});if(moved)form.insertBefore(bubble,actions||null);};

function renderMetadataMatches(job){const box=$('#description-metadata');if(!box)return;const metadata=json(job?.metadata_json||job?.metadata,{});const matches=Array.isArray(metadata.matches)?metadata.matches:[];const providers=metadata.providers||{};const providerSummary=Object.entries(providers).map(([name,item])=>`${name}: ${item.status||'unknown'}`).join(' · ');if(!matches.length){box.innerHTML=`<div class="metadata-panel"><div><p class="eyebrow">Metadata matching</p><strong>${esc(metadata.status||'No metadata matches')}</strong><p class="field-note">${esc(metadata.error||'Configure provider tokens in Settings, then refresh metadata for suggestions.')}</p>${providerSummary?`<small class="field-note">${esc(providerSummary)}</small>`:''}</div><button type="button" class="small-button" id="refresh-metadata">Refresh metadata</button></div>`;return;}const selected=metadata.selected||{};box.innerHTML=`<div class="metadata-panel"><div class="metadata-panel-head"><div><p class="eyebrow">Metadata matches</p><strong>${matches.length} candidate${matches.length===1?'':'s'} found for “${esc(metadata.query||job.folder_name)}”</strong><p class="field-note">Review the suggestions and choose one to copy its title and tags into this draft. Nothing is uploaded automatically.</p></div><button type="button" class="small-button" id="refresh-metadata">Refresh metadata</button></div><div class="metadata-match-grid">${matches.map((match,index)=>{const active=selected.provider===match.provider&&selected.provider_id===match.provider_id;return `<article class="metadata-match ${active?'selected':''}"><div class="metadata-match-head"><span class="badge blue">${esc(match.provider)}</span><strong>${esc(match.confidence)}% match</strong></div><h3>${esc(match.title||match.provider_id||'Untitled result')}</h3><div class="metadata-match-body">${match.studio?`<span><b>Studio</b> ${esc(match.studio)}</span>`:''}${match.site?`<span><b>Site</b> ${esc(match.site)}</span>`:''}${match.date?`<span><b>Date</b> ${esc(match.date)}</span>`:''}${match.performers?.length?`<span><b>Performers</b> ${esc(match.performers.join(', '))}</span>`:''}${match.tags?.length?`<span><b>Tags</b> ${esc(match.tags.join(', '))}</span>`:''}</div>${match.url?`<a href="${esc(match.url)}" target="_blank" rel="noreferrer">Open provider result</a>`:''}<button type="button" class="small-button ${active?'good':''}" data-select-metadata-provider="${esc(match.provider)}" data-select-metadata-index="${index}">${active?'Selected':'Use this match'}</button></article>`;}).join('')}</div>${providerSummary?`<small class="field-note metadata-provider-summary">${esc(providerSummary)}</small>`:''}</div>`;}
const originalOpenDescriptionWithMetadata=openDescription;
openDescription=async function(id){await originalOpenDescriptionWithMetadata(id);const job=await api(`/api/jobs/${id}`);renderMetadataMatches(job);};
