function statusBadge(status){const cls=['Completed'].includes(status)?'green':['Failed','Blocked','Duplicate'].includes(status)?'red':['Awaiting Description','Final Review'].includes(status)?'orange':['Uploading','Creating Torrent','Scanning','Generating Images','Identifying Metadata'].includes(status)?'blue':'';return `<span class="badge ${cls}">${esc(status)}</span>`;}
function jobProgressHtml(job){const raw=Number(job.progress);const progress=Number.isFinite(raw)?Math.max(0,Math.min(100,raw)):0;const status=String(job.status||'');const explanations={'Detected':'Queued and waiting to start','Waiting For Files':'Waiting for the release files to finish copying','Scanning':'Scanning the release media','Identifying Metadata':'Checking ThePornDB, StashDB, and javinfo for matching metadata','Generating Images':'Creating preview images with Thumb It','Creating Torrent':'Building the private torrent','Validating Tracker':'Checking the tracker settings','Uploading Images':'Preparing images for upload','Awaiting Description':'Waiting for you to build the upload description','Final Review':'Waiting for your final review before upload','Uploading':'Submitting the torrent to the tracker','Completed':'Upload completed successfully','Failed':'Processing stopped because of an error','Duplicate':'Skipped because a duplicate was found','Blocked':'Waiting for an issue to be resolved'};const explanation=job.error&&status==='Failed'?`Processing stopped: ${job.error}`:(explanations[status]||job.stage||status||'Queued');const tone=status==='Completed'?'complete':['Failed','Blocked','Duplicate'].includes(status)?'error':['Awaiting Description','Final Review','Waiting For Files'].includes(status)?'waiting':'active';return `<div class="job-progress"><div class="job-progress-head"><span>What's happening: ${esc(explanation)}</span><strong>${progress.toFixed(0)}% complete</strong></div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.toFixed(0)}" aria-label="${esc(explanation)}"><div class="progress-fill ${tone}" style="width:${progress}%"></div></div></div>`;}
