function cleanFilenameDisplay(value){return String(value||'').replace(/_/g,' ').replace(/\.{2,}/g,' ').replace(/\s+/g,' ').trim().replace(/^[ ._-]+|[ ._-]+$/g,'');}
function mediaInfoBbcode(job){const media=json(job?.media_json||job?.media,{});const videos=Array.isArray(media.videos)?media.videos:[];const duration=(value)=>{const seconds=Number(value);if(!Number.isFinite(seconds))return String(value||'Unknown');const total=Math.max(0,Math.round(seconds));const hours=Math.floor(total/3600);const minutes=Math.floor((total%3600)/60);const secs=total%60;return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;};const frameRate=(value)=>{const parts=String(value||'').split('/').map(Number);if(parts.length===2&&parts[1])return `${(parts[0]/parts[1]).toFixed(2).replace(/\.00$/,'')} fps`;return value?`${value} fps`:'Unknown';};const lines=[`[size=20][b]${cleanFilenameDisplay(job.upload_title||job.torrent_internal_name||job.folder_name)}[/b][/size]`,'','[center][upimg0][/center]','','[b]MediaInfo[/b]','','[b]Release summary[/b]',`[b]Folder:[/b] ${cleanFilenameDisplay(media.folder_name||job.folder_name)}`,`[b]Files:[/b] ${media.file_count??job.file_count??0}`,`[b]Total size:[/b] ${formatSize(media.total_size??job.total_size??0)}`,`[b]Video files:[/b] ${media.video_count??job.video_count??videos.length}`];videos.forEach((video,index)=>{const resolution=video.width&&video.height?`${video.width}x${video.height} (${video.height}p)`:'';lines.push('',`[b]Video ${index+1}[/b]`,`[b]File:[/b] ${cleanFilenameDisplay(video.file||'Unknown')}`,`[b]Duration:[/b] ${duration(video.duration)}`,`[b]Resolution:[/b] ${resolution||'Unknown'}`,`[b]Video codec:[/b] ${video.video_codec||'Unknown'}`,`[b]Audio codec:[/b] ${video.audio_codec||'Unknown'}`,`[b]Frame rate:[/b] ${frameRate(video.frame_rate)}`,`[b]Pixel format:[/b] ${video.pixel_format||'Unknown'}`,`[b]Audio channels:[/b] ${video.audio_channels||'Unknown'}`,`[b]Language:[/b] ${video.language||'Unknown'}`);});return lines.join('\n');}
