/* Sidebar identity: Idea 4. Version and badge are driven by the same UpdateChecker data as Settings. */
function renderBrand(){
  if(!state.data)return;
  const localVersion=String(state.data.app_version||state.update?.local_version||'1.0 Beta').replace(/^v/i,'');
  const update=state.update||state.data.update||null;
  const name=$('#brand-name');
  const version=$('#brand-version');
  const badge=$('#brand-update-status');
  if(name)name.textContent='Pumpkin Forge';
  if(version)version.textContent=localVersion;
  if(!badge)return;

  let label='LOCAL';
  let tone='local';
  let title=`Installed version v${localVersion}. Open Settings for GitHub update checking.`;
  if(update?.status==='Update available'){
    label='UPDATE';
    tone='update';
    title=`GitHub v${update.remote_version} is available. Installed: v${localVersion}. Open Settings for details.`;
  }else if(update?.status==='Up to date'){
    label='CURRENT';
    tone='current';
    title=`v${localVersion} matches the latest GitHub version.`;
  }else if(update?.status==='Local version is newer'){
    label='DEV';
    tone='dev';
    title=`Installed v${localVersion} is newer than GitHub v${update.remote_version}.`;
  }else if(update?.status==='Error'){
    label='CHECK';
    tone='error';
    title=update.error?`Last GitHub check failed: ${update.error}`:'Last GitHub update check failed.';
  }else if(update?.status==='Disabled'){
    label='LOCAL';
    tone='local';
    title=`Installed version v${localVersion}. GitHub update checks are disabled.`;
  }else if(update?.status==='Not checked'){
    label='LOCAL';
    tone='local';
    title=`Installed version v${localVersion}. GitHub has not been checked yet.`;
  }
  badge.textContent=label;
  badge.className=`brand-status ${tone}`;
  badge.title=title;
}

const renderUpdateWithSidebarVersion=renderUpdate;
renderUpdate=()=>{
  renderUpdateWithSidebarVersion();
  renderBrand();
};

// Settings groups can be folded without changing the existing visual theme.
function collapseSettingsGroups(){
  document.querySelectorAll('#settings-form > .settings-bubble').forEach(section=>{
    if(section.tagName.toLowerCase()==='details')return;
    const details=document.createElement('details');
    details.className=section.className;
    while(section.firstChild)details.appendChild(section.firstChild);
    const head=details.querySelector(':scope > .settings-bubble-head');
    if(head){
      const summary=document.createElement('summary');
      summary.className='settings-bubble-summary';
      summary.appendChild(head);
      details.insertBefore(summary,details.firstChild);
    }
    const title=details.querySelector(':scope > summary h3')?.textContent.trim()||'settings';
    const key=`pumpkin-forge-settings-v2-${title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;
    let saved=null;
    try{saved=localStorage.getItem(key);}catch(_){/* storage may be unavailable */}
    details.open=saved===null?false:saved==='open';
    details.addEventListener('toggle',()=>{try{localStorage.setItem(key,details.open?'open':'closed');}catch(_){}},{once:false});
    section.replaceWith(details);
  });
}

