  const selected=trackers.find(item=>String(item.id)===selectedId)||(selectedId==='__new_external__'?{tracker_type:'external_unit3d'}:trackers[0]||{tracker_type:'bitporn'});
  form.innerHTML=`<div class="field full"><label>Tracker profile</label><select id="tracker-profile" aria-label="Select tracker profile">${trackers.map(item=>`<option value="${esc(item.id)}" ${String(item.id)===selectedId?'selected':''}>${esc(item.name)}${item.tracker_type==='external_unit3d'?' · External UNIT3D':''}</option>`).join('')}<option value="__new_external__" ${selectedId==='__new_external__'?'selected':''}>＋ Add external UNIT3D tracker</option></select><small class="field-note">Select an existing profile to edit, or add a separate external UNIT3D profile.</small></div>${externalTrackerFormHtml(selected)}`;
