// Settings use top-level sections so users only see the controls they are working on.
function renderSettingsTabs(){
  const tabs=$('#settings-tabs');
  const grid=$('#settings-grid');
  if(!tabs||!grid)return;
  const options=[
    ['application','Application','settings-core-panel','Application'],
    ['thumbit','Thumb It','settings-core-panel','Thumbnail generation'],
    ['upload','Upload','settings-core-panel','Upload and workflow'],
    ['updates','Updates','settings-core-panel','Application updates'],
    ['metadata','Metadata','settings-core-panel','Metadata providers'],
    ['tracker','Tracker','tracker-settings-panel',''],
    ['folders','Folders','folder-settings-panel','']
  ];
  const active=options.some(item=>item[0]===state.settingsTab)?state.settingsTab:'application';
  state.settingsTab=active;
  tabs.innerHTML=options.map(([id,label])=>`<button type="button" class="settings-tab ${id===active?'active':''}" data-settings-tab="${id}">${label}</button>`).join('');
  const selected=options.find(item=>item[0]===active);
  const core=grid.querySelector('#settings-core-panel');
  const tracker=grid.querySelector('#tracker-settings-panel');
  const folders=grid.querySelector('#folder-settings-panel');
  if(core)core.hidden=selected[2]!=='settings-core-panel';
  if(tracker)tracker.hidden=selected[2]!=='tracker-settings-panel';
  if(folders)folders.hidden=selected[2]!=='folder-settings-panel';
  grid.classList.add('settings-tab-focused');
  if(core){
    core.querySelectorAll('#settings-form > .settings-bubble').forEach(section=>{
      const title=section.querySelector('h3')?.textContent.trim()||'';
      const matches=title===selected[3];
      section.hidden=!matches;
      if(matches&&section.tagName.toLowerCase()==='details')section.open=true;
    });
    const updateCard=$('#update-card');
    if(updateCard)updateCard.hidden=active!=='updates';
  }
}

document.addEventListener('click',event=>{
  const tab=event.target.closest('#settings-tabs [data-settings-tab]');
  if(!tab)return;
  event.preventDefault();
  state.settingsTab=tab.getAttribute('data-settings-tab')||'application';
  renderSettingsTabs();
});

/* Per-job clear control: remove the queue record while preserving the original release folder. */
const originalRenderJobsWithClear=renderJobs;
renderJobs=(target,jobs)=>{
  originalRenderJobsWithClear(target,jobs);
  const container=$(target);
  if(!container)return;
  container.querySelectorAll('.job-row').forEach((row,index)=>{
    const job=jobs[index];
    const actions=row.querySelector('.job-actions');
    if(!job||!actions||actions.querySelector('[data-clear-job]'))return;
    actions.insertAdjacentHTML('beforeend',`<button type="button" class="small-button warn" data-clear-job="${job.id}" title="Remove this job from Pumpkin Forge">Clear</button>`);
  });
};

document.addEventListener('click',async event=>{
  const clear=event.target.closest('[data-clear-job]');
  if(!clear)return;
  const jobId=clear.dataset.clearJob;
  const job=state.data?.jobs?.find(item=>String(item.id)===String(jobId));
  const name=job?.upload_title||job?.folder_name||'this job';
  if(!confirm(`Clear “${name}” from Pumpkin Forge?\n\nThe original release files will be left untouched.`))return;
  clear.disabled=true;
  try{
    await api(`/api/jobs/${jobId}/clear`,{method:'POST',body:'{}'});
    if(String(state.selectedDescription)===String(jobId))state.selectedDescription=null;
    if(String(state.selectedReview)===String(jobId))state.selectedReview=null;
    if(String(state.selectedLogs)===String(jobId)){state.selectedLogs=null;state.logsJob=null;}
    toast('Job cleared');
    await load();
  }catch(error){clear.disabled=false;toast(error.message,'error');}
});

/* Default description layout: keep the agreed release-info and screenshot
   structure for new jobs and older autogenerated descriptions. */
function defaultDescriptionBbcode(job){
  const media=json(job?.media_json||job?.media,{});
  const images=Array.isArray(job?.images)?job.images:[];
  const separator='[color=#00d9ff]━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━[/color]';
  const title=cleanFilenameDisplay(job.upload_title||job.torrent_internal_name||job.folder_name||'Release');
  const coverIndex=images.findIndex(image=>image.image_type==='cover'||/^centerlongest/i.test(String(image.file_name||'')));
  const screenshotIndices=images.map((image,index)=>({image,index})).filter(({image})=>/^(?:center\d+|still\d*)/i.test(String(image.file_name||''))||image.image_type==='preview').map(item=>item.index).slice(0,5);
  const thumbIndices=images.map((image,index)=>({image,index})).filter(({image})=>/^sheet/i.test(String(image.file_name||''))).map(item=>item.index).slice(0,2);
  const imageTags=indices=>indices.map(index=>`[upimg${index}]`).join(' ');
  const duration=value=>{const seconds=Number(value);if(!Number.isFinite(seconds))return String(value||'Unknown');const total=Math.max(0,Math.round(seconds));return `${String(Math.floor(total/3600)).padStart(2,'0')}:${String(Math.floor((total%3600)/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;};
  const frameRate=value=>{const parts=String(value||'').split('/').map(Number);if(parts.length===2&&parts[1])return `${(parts[0]/parts[1]).toFixed(2).replace(/\.00$/,'')} fps`;return value?`${value} fps`:'Unknown';};
  const videos=Array.isArray(media.videos)?media.videos:[];
  const info=[`[b]Files:[/b] ${media.file_count??job.file_count??0}`,`[b]Total size:[/b] ${formatSize(media.total_size??job.total_size??0)}`,`[b]Video files:[/b] ${media.video_count??job.video_count??videos.length}`];
  videos.forEach((video,index)=>{const resolution=video.width&&video.height?`${video.width}x${video.height} (${video.height}p)`:'Unknown';info.push('',`[b]Video ${index+1}[/b]`,`[b]Duration:[/b] ${duration(video.duration)}`,`[b]Resolution:[/b] ${resolution}`,`[b]Video codec:[/b] ${video.video_codec||'Unknown'}`,`[b]Audio codec:[/b] ${video.audio_codec||'Unknown'}`,`[b]Frame rate:[/b] ${frameRate(video.frame_rate)}`,`[b]Pixel format:[/b] ${video.pixel_format||'Unknown'}`,`[b]Audio channels:[/b] ${video.audio_channels||'Unknown'}`,`[b]Language:[/b] ${video.language||'Unknown'}`);});
  const lines=['[center]',separator,`[size=20][b]${title}[/b][/size]`,separator,'[/center]'];
  if(coverIndex>=0)lines.push('',`[center][upimg${coverIndex}][/center]`);
  lines.push('', '[center]', separator, '[size=18][b]RELEASE INFO[/b][/size]', separator, ...info, '[/center]', '', '[center]', separator, '[size=18][b]SCREENSHOTS[/b][/size]', separator, '[/center]');
  if(screenshotIndices.length)lines.push('',`[center]${imageTags(screenshotIndices)}[/center]`);
  if(thumbIndices.length)lines.push('',`[center]${imageTags(thumbIndices)}[/center]`);
  return lines.join('\n');
}

const originalOpenDescriptionWithDefaultLayout=openDescription;
openDescription=async function(id){await originalOpenDescriptionWithDefaultLayout(id);const area=$('#d-description');if(!area)return;const current=area.value;const looksAutogenerated=!current.trim()||(current.includes('[b]MediaInfo[/b]')&&!/SCREENSHOTS/i.test(current));if(looksAutogenerated){const job=await api(`/api/jobs/${id}`);area.value=defaultDescriptionBbcode(job);area.dispatchEvent(new Event('input',{bubbles:true}));}};
